@startuml

enum BuildingMaterial {
  wood
  brick
  concrete
}

class House {
  +address: string
  +buildingMaterial: BuildingMaterial
}

abstract class Basement {
  +size: string
  +name: string
}

class EarthBasement extends Basement {
  +humidityLevel: float
}

class ConcreteBasement extends Basement {}

abstract class SemiDetached extends House {}

class SemiDetachedWithCarport extends SemiDetached {
  +hasOwnGarden: boolean
  +numberOfWindows: int
}

class SemiDetachedWithGarage extends SemiDetached {
  +hasOwnGarden: boolean
  +numberOfWindows: int
}

class Carport {
  +isDoubleCarport: boolean
  +hasFlatRoof: boolean
}

class Garage {
  +hasAutomaticGarageDoor: boolean
}

class Company {
  +name: string
  +address: string
}

class JobLog {
  +numberOfHours: float
  +agreedPrice: float
}

House "1" *-- "0..1" Basement
SemiDetachedWithCarport "1" -- "2" Carport
SemiDetachedWithGarage "1" -- "1" Garage
House "1" -- "*" JobLog
JobLog "*" -- "1" Company
House "1" -- "*" Company

@enduml

